import{_ as t,o as a,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Juggling Petabytes: Managing Ceph at Scale with Ceph-ansible - Matthew Vernon","description":"","frontmatter":{"title":"Juggling Petabytes: Managing Ceph at Scale with Ceph-ansible - Matthew Vernon","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","分布式存储","Ceph","ansible","自动化","存储集群管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Juggling_Petabytes_-_Managing_Ceph_at_Scale_with_Ceph-ansible_-_Matthew_Vernon.md","filePath":"posts/2019/Juggling_Petabytes_-_Managing_Ceph_at_Scale_with_Ceph-ansible_-_Matthew_Vernon.md","lastUpdated":1780459816000}'),n={name:"posts/2019/Juggling_Petabytes_-_Managing_Ceph_at_Scale_with_Ceph-ansible_-_Matthew_Vernon.md"};function _(p,e,s,g,o,r){return a(),l("div",null,[...e[0]||(e[0]=[i("<p>Saenger研究院的Ceph存储集群部署、管理及经验分享会议纪要：</p><p>会议介绍了Saenger研究院的概况，包括其在基因测序和基因组分析领域的贡献，以及其高吞吐量计算集群和存储资源。Saenger研究院自2016年开始使用Ceph存储，目前拥有51个节点，18PB的原始容量，并拥有一个测试集群和一个灾备站点。</p><p><strong>会议主要内容包括</strong>：</p><p><strong>一、Ceph存储集群部署</strong></p><ul><li>使用Ansible和Ceph Ansible Wall进行集群管理。</li><li>集群配置包括Supermicro服务器、Mellanox 100G网络和SAS驱动器。</li><li>使用Collectd收集指标，Nagios进行监控。</li><li>编写脚本监控OSD状态和硬盘健康状况。</li></ul><p><strong>二、Ceph存储集群升级</strong></p><ul><li>从Jewel版本升级到Luminous版本，并计划迁移到Nautilus版本。</li><li>升级过程相对顺利，但迁移到BlueStore时遇到挑战。</li></ul><p><strong>三、Ceph存储集群使用经验</strong></p><ul><li>Ceph存储集群易于扩展、高可靠性和高性能。</li><li>主要用于存储基因测序数据，并通过Rados Gateway提供S3存储服务。</li></ul><p><strong>四、Ceph存储集群的挑战</strong></p><ul><li>Rados Gateway服务管理复杂。</li><li>大型OMAP对象处理。</li><li>无法自动迁移数据到纠删码池。</li><li>无法自动缩减池大小。</li><li>部署过程复杂。</li></ul><p><strong>五、行动计划</strong></p><ul><li>使用Ceph的新功能，如纠删码和自动缩减池大小。</li><li>优化Rados Gateway服务管理。</li><li>简化部署过程。</li></ul><p><strong>六、会议总结</strong></p><p>会议分享了Saenger研究院在Ceph存储集群部署、管理及使用方面的经验，并讨论了遇到的挑战和未来的改进计划。</p>",15)])])}const C=t(n,[["render",_]]);export{u as __pageData,C as default};
